            for (int j = 0; j < TN; ++j) bReg[j] = Bs[buf][kk][colBase + j];
            #pragma unroll
            for (int i = 0; i < TM; ++i)
                #pragma unroll
                for (int j = 0; j < TN; ++j)
                    acc[i][j] += aReg[i] * bReg[j];
        }

        __syncthreads();  // reader/writer turn-around on shared buffers
    }

    // Store the register tile to C.
    const int goutRow = blockRow + rowBase;
    const int goutCol = blockCol + colBase;
    #pragma unroll
    for (int i = 0; i < TM; ++i)
        #pragma unroll
        for (int j = 0; j < TN; ++j)
            C[(size_t)(goutRow + i) * N + (goutCol + j)] = acc[i][j];
}

// ---------------------------------------------------------------------------
// Fallback: arbitrary N. Register-blocked + shared tiled, guarded loads.
// ---------------------------------------------------------------------------
__global__ static void gemmKernelGuarded(const float* __restrict__ A,
                                         const float* __restrict__ B,
                                         float* __restrict__ C, int N) {
    __shared__ float As[BM][BK + 2];
    __shared__ float Bs[BK][BN + 2];

    const int numKTiles = (N + BK - 1) / BK;

    const int blockRow = blockIdx.y * BM;
    const int blockCol = blockIdx.x * BN;

    const int row = blockRow + threadIdx.y * TM;
    const int col = blockCol + threadIdx.x * TN;

    float acc[TM][TN];
    #pragma unroll
    for (int i = 0; i < TM; ++i)
        #pragma unroll
        for (int j = 0; j < TN; ++j) acc[i][j] = 0.0f;

    // Cooperative load of the A and B shared tiles (BM*BK + BK*BN entries,
    // 256 threads total => loop of ceil(...)).
    const int aTotal = BM * BK;
    const int bTotal = BK * BN;
    const int tid = threadIdx.y * BX + threadIdx.x;
    const int aIters = (aTotal + 255) / 256;
    const int bIters = (bTotal + 255) / 256;

    for (int t = 0; t < numKTiles; ++t) {
        const int kStart = t * BK;

        // ---- load A tile (BM x BK) ----
        for (int e = 0; e < aIters; ++e) {
            const int idx = tid + e * 256;
            if (idx < aTotal) {
                const int r = idx / BK;
                const int k = idx % BK;
                const int gRow = blockRow + r;
                const int gCol = kStart + k;
                As[r][k] = (gRow < N && gCol < N) ? A[(size_t)gRow * N + gCol] : 0.0f;
            }
        }

        // ---- load B tile (BK x BN) ----
        for (int e = 0; e < bIters; ++e) {
            const int idx = tid + e * 256;
            if (idx < bTotal) {
                const int k = idx / BN;
                const int c = idx % BN;
                const int gRow = kStart + k;
                const int gCol = blockCol + c;
                Bs[k][c] = (gRow < N && gCol < N) ? B[(size_t)gRow * N + gCol] : 0.0f;
            }
        }
        __syncthreads();

        #pragma unroll
        for (int kk = 0; kk < BK; ++kk) {
            float aReg[TM], bReg[TN];
            #pragma unroll
            for (int i = 0; i < TM; ++i) aReg[i] = As[threadIdx.y * TM + i][kk];
            #pragma unroll
            for (int j = 0; j < TN; ++j) bReg[j] = Bs[kk][threadIdx.x * TN + j];
            #pragma unroll
            for (int i = 0; i < TM; ++i)
                #pragma unroll
                for (int j = 0; j < TN; ++j)
                    acc[i][j] += aReg[i] * bReg[j];
        }
        __syncthreads();
    }

    // Guarded store.
    #pragma unroll
    for (int i = 0; i < TM; ++i) {
        const int r = blockRow + threadIdx.y * TM + i;
        if (r >= N) break;
        #pragma unroll
        for (int j = 0; j < TN; ++j) {
            const int c = blockCol + threadIdx.x * TN + j;
            if (c < N) C[(size_t)r * N + c] = acc[i][j];
        }
    }
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    if (N % BM == 0 && N % BN == 0 && N % BK == 0) {
        dim3 block(BX, BY);
        dim3 grid(N / BN, N / BM);
        gemmKernelAligned<<<grid, block>>>(dA, dB, dC, N);
    } else {
        dim3 block(BX, BY);
        dim3 grid((N + BN - 1) / BN, (N + BM - 1) / BM);
        gemmKernelGuarded<<<grid, block>>>(dA, dB, dC, N);
    }
}

