// A tile: BM x BK floats loaded row-major (BM rows).
// 16-byte groups: each row splits into BK/4 groups (GPB).
constexpr int GPB = BK / 4;                        // groups per row
#pragma unroll
for (int e = 0; e < (BM * BK) / (4 * 256); ++e) {  // groups / threads
    const int g = tid + e * 256;                    // 0..(BM*BK/4)-1
    const int r = g / GPB;                          // which row
    const int k4 = g % GPB;                         // cols group
    __pipeline_memcpy_async(
        &As[buf][r][k4 * 4],
        A + (size_t)(blockRow + r) * N + aK + k4 * 4,
        CPASYNC_TX);
}

