edits.newText:
// ---- helper: issue cp.async loads for K-tile "kt" into buffer "buf" ----
auto issueLoads = [&](int buf, int kt) {
    const int aK = kt * BK;
    const int bK = kt * BK;

    // A tile: BM x BK floats, loaded in 16-byte (4-float) groups.
    // GPB = groups per row; numA = total 16-byte tokens.
    constexpr int GPB = BK / 4;
    constexpr int numA = (BM * BK) / 4;
    constexpr int aIters = (numA + 255) / 256;
    #pragma unroll
    for (int e = 0; e < aIters; ++e) {
        const int g = tid + e * 256;
        if (g < numA) {
            const int r = g / GPB;      // which A-row
            const int k4 = g % GPB;     // cols group
            __pipeline_memcpy_async(
                &As[buf][r][k4 * 4],
                A + (size_t)(blockRow + r) * N + aK + k4 * 4,
                CPASYNC_TX);
        }
    }

    // B tile: BK x BN floats, row-major in (K, N).
    constexpr int GPN = BN / 4;
    constexpr int numB = (BK * BN) / 4;
    constexpr int bIters = (numB + 255) / 256;
    #pragma unroll
    for (int e = 0; e < bIters; ++e) {
        const int g = tid + e * 256;
        if (g < numB) {
            const int kc = g / GPN;     // k-row
            const int c4 = g % GPN;     // cols group
            __pipeline_memcpy_async(
                &Bs[buf][kc][c4 * 4],
                B + (size_t)(bK + kc) * N + blockCol + c4 * 4,
                CPASYNC_TX);
        }
    }
};

