// Compare launchGemm (gemm.cu) vs cuBLAS for a fixed NxN sgemm.
#include "src/gemm.cuh"
#include <cublas_v2.h>
#include <cuda_runtime.h>
#include <cstdio>
#include <cstdlib>
#include <vector>

#define CK(c) do{cudaError_t e=(c); if(e!=cudaSuccess){fprintf(stderr,"CUDA %s\n",cudaGetErrorString(e));exit(1);}}while(0)

int main(int argc,char**argv){
    int N = argc>1?atoi(argv[1]):2048;
    size_t bytes=(size_t)N*N*sizeof(float);
    float *dA,*dB,*dC1,*dC2;
    CK(cudaMalloc(&dA,bytes)); CK(cudaMalloc(&dB,bytes));
    CK(cudaMalloc(&dC1,bytes)); CK(cudaMalloc(&dC2,bytes));
    std::vector<float> A(N*N),B(N*N);
    for(size_t i=0;i<(size_t)N*N;i++){A[i]=(float)(i%7)/7.0f-0.5f;B[i]=(float)(i%5)/5.0f-0.5f;}
    CK(cudaMemcpy(dA,A.data(),bytes,cudaMemcpyHostToDevice));
    CK(cudaMemcpy(dB,B.data(),bytes,cudaMemcpyHostToDevice));

    cublasHandle_t h; cublasCreate(&h);
    float alpha=1.0f,beta=0.0f;

    // cuBLAS (C = alpha*A*B + beta*C). Row-major => use CUBLAS_OP_N; cublas is col-major
    // but for square with op N it computes C(rm) = A*B correctly since both sides row-major.
    int repeats=50;  // warmup + measure
    for(int i=0;i<repeats;i++)
        cublasSgemm(h,CUBLAS_OP_N,CUBLAS_OP_N,N,N,N,&alpha,dA,N,dB,N,&beta,dC2,N);
    CK(cudaDeviceSynchronize());
    cudaEvent_t x,y; cudaEventCreate(&x); cudaEventCreate(&y);
    float best=1e30f;
    for(int r=0;r<10;r++){
        cudaEventRecord(x);
        for(int i=0;i<repeats;i++)
            cublasSgemm(h,CUBLAS_OP_N,CUBLAS_OP_N,N,N,N,&alpha,dA,N,dB,N,&beta,dC2,N);
        cudaEventRecord(y); cudaEventSynchronize(y);
        float ms; cudaEventElapsedTime(&ms,x,y);
        float per=ms/repeats; if(per<best)best=per;
    }
