const int buf = t & 1;

// Double-vectorized inner loop: A and B both loaded as float4.
#pragma unroll
for (int kkk4 = 0; kkk4 < BK; kkk4 += 4) {
    float4 av[TM];
    #pragma unroll
    for (int i = 0; i < TM; ++i)
        av[i] = *reinterpret_cast<const float4*>(&As[buf][rowBase + i][kkk4]);
    #pragma unroll
    for (int p = 0; p < 4; ++p) {
        #pragma unroll
        for (int j4 = 0; j4 < TN; j4 += 4) {
            const float4 bv =
                *reinterpret_cast<const float4*>(&Bs[buf][kkk4 + p][colBase + j4]);
            #pragma unroll
            for (int i = 0; i < TM; ++i) {
                const float a = (p == 0) ? av[i].x
                               : (p == 1) ? av[i].y
                               : (p == 2) ? av[i].z : av[i].w;
                acc[i][j4 + 0] += a * bv.x;
                acc[i][j4 + 1] += a * bv.y;
                acc[i][j4 + 2] += a * bv.z;
                acc[i][j4 + 3] += a * bv.w;
            }
        }
    }
}

