#define CPASYNC_TX 16  // bytes per cp.async (4 floats)

// cp.async.cg: bypass L1 when staging global->shared so the compute (LDS)
// shared-load traffic keeps full L1 bandwidth.
__device__ __forceinline__ void cpAsyncCG(float* smem, const float* gmem) {
    unsigned s = (unsigned)__cvta_generic_to_shared(smem);
    asm volatile("cp.async.cg.shared.global [%0], [%1], 16;\n" ::
                 "r"(s), "l"(gmem));
}

