arguments.command:
cd /problem && ./gemm -c 2>&1 | grep -E "MSE|MISMATCH|Performance" && echo "=== extra size check (build a custom validator) ===" && cat > /tmp/validate.cu <<'EOF'
#include "src/gemm.cuh"
#include <cuda_runtime.h>
#include <cstdio>
#include <vector>
#include <random>
#define CK(c) do{cudaError_t e=(c);if(e!=cudaSuccess){fprintf(stderr,"%s\n",cudaGetErrorString(e));exit(1);}}while(0)
int main(){
  int sizes[]={512,768,1000,1024,1536,2048,2017,4096};
  for(int s:sizes){
    int N=s; std::vector<float>A(N*N),B(N*N),C(N*N),R(N*N);
    std::mt19937 g(42); std::uniform_real_distribution<float>d(-1,1);
    for(auto&x:A)x=d(g); for(auto&x:B)x=d(g);
    size_t by=(size_t)N*N*4; float *da,*db,*dc;
    CK(cudaMalloc(&da,by));CK(cudaMalloc(&db,by));CK(cudaMalloc(&dc,by));
    CK(cudaMemcpy(da,A.data(),by,cudaMemcpyHostToDevice));
    CK(cudaMemcpy(db,B.data(),by,cudaMemcpyHostToDevice));
    launchGemm(da,db,dc,N); CK(cudaDeviceSynchronize());
    CK(cudaMemcpy(C.data(),dc,by,cudaMemcpyDeviceToHost));
    for(int i=0;i<N;i++)for(int j=0;j<N;j++){double a=0;for(int k=0;k<N;k++)a+=(double)A[i*N+k]*B[k*N+j];R[i*N+j]=(float)a;}
    double sse=0; for(size_t i=0;i<(size_t)N*N;i++){double dd=C[i]-R[i];sse+=dd*dd;}
    printf("N=%4d MSE=%.3e %s\n",N,sse/(N*N), sse/(N*N)<1e-3?"ok":"FAIL");
    cudaFree(da);cudaFree(db);cudaFree(dc);
  }
  return 0;
}
EOF
nvcc -O3 -std=c++14 -use_fast_math -arch=sm_86 /tmp/validate.cu src/gemm.cu -o /tmp/validate 2>&1|grep -i error; /tmp/validate 2>&1

