#include "gemm.cuh"

#include <cuda_runtime.h>
#include <cuda_pipeline.h>

// ===========================================================================
//  Optimized tiled GEMM for Ampere (sm_86, NVIDIA A40).
//
//  The primary kernel uses shared-memory tiling + register blocking, Ampere's
//  cp.async for software-pipelined (double-buffered) global->shared loads, and
//  padded shared buffers to avoid bank conflicts. It runs when N divides
//  evenly by the block tile (the steady-state case). A guarded fallback
//  handles arbitrary N correctly.
// ===========================================================================

// ---------------------------------------------------------------------------
// Block-tile parameters.
// ---------------------------------------------------------------------------
#define BM 128   // rows of C-tile per block
#define BN 128   // cols of C-tile per block
#define BK 16    // width of the K-strip loaded into shared per stage
#define BY 16    // thread rows
#define BX 16    // thread cols -> block is 256 threads
#define TM (BM / BY)   // register tile rows per thread = 8
#define TN (BN / BX)   // register tile cols per thread = 8

#define CPASYNC_TX 16  // bytes per cp.async (4 floats)

// ---------------------------------------------------------------------------
// Fast path: s_sizes that are exact multiples of BM (and therefore BK).
// ---------------------------------------------------------------------------
__global__ static void gemmKernelAligned(const float* __restrict__ A,
                                         const float* __restrict__ B,
                                         float* __restrict__ C, int N) {
    // Double-buffered shared tiles, padded to avoid bank conflicts.
    __shared__ float As[2][BM][BK + 2];
    __shared__ float Bs[2][BK][BN + 2];

    const int numKTiles = N / BK;

    const int blockRow = blockIdx.y * BM;
    const int blockCol = blockIdx.x * BN;

    const int rowBase = threadIdx.y * TM;   // 0..15 -> 0,8,...,120
    const int colBase = threadIdx.x * TN;   // 0..15 -> 0,8,...,120
    const int tid = threadIdx.y * BX + threadIdx.x;

    // ---- helper: issue cp.async loads for K-tile "kt" into buffer "buf" ----
    auto issueLoads = [&](int buf, int kt) {
        const int aK = kt * BK;
        const int bK = kt * BK;

        // A tile: BM x BK floats loaded row-major (BM rows).
        // 16-byte groups: each row (BK=16 floats) splits into BK/4=4 groups.
        #pragma unroll
        for (int e = 0; e < (BM * BK) / (4 * 256); ++e) {  // 2
            const int g = tid + e * 256;                    // 0..511
            const int r = g >> 2;                           // which row (0..127)
            const int k4 = g & 3;                           // cols group (0..3)
            __pipeline_memcpy_async(
                &As[buf][r][k4 * 4],
                A + (size_t)(blockRow + r) * N + aK + k4 * 4,
                CPASYNC_TX);
        }

        // B tile: BK x BN floats, row-major in (K, N).
        #pragma unroll
        for (int e = 0; e < (BK * BN) / (4 * 256); ++e) {  // 2
            const int g = tid + e * 256;
            const int kc = g >> 5;                          // krow 0..15
            const int c4 = g & 31;                          // cols group 0..31
            __pipeline_memcpy_async(
                &Bs[buf][kc][c4 * 4],
                B + (size_t)(bK + kc) * N + blockCol + c4 * 4,
                CPASYNC_TX);
        }
    };

    // Software pipeline with double buffering across the K dimension.
    float acc[TM][TN];
    #pragma unroll
    for (int i = 0; i < TM; ++i)
        #pragma unroll
        for (int j = 0; j < TN; ++j) acc[i][j] = 0.0f;

    // Prologue: load tile 0 into buffer 0.
    issueLoads(0, 0);
    __pipeline_commit();

    for (int t = 0; t < numKTiles; ++t) {
        // Prefetch next K-tile into the other buffer.
        if (t + 1 < numKTiles) {
            issueLoads((t + 1) & 1, t + 1);
            __pipeline_commit();
        }

        // Wait for the current tile's loads (keep the prefetch in flight).
        __pipeline_wait_prior(t + 1 < numKTiles ? 1 : 0);
        __syncthreads();

        const int buf = t & 1;

        #pragma unroll
        for (int kk = 0; kk < BK; ++kk) {
            float aReg[TM], bReg[TN];
            #pragma unroll
            for (int i = 0; i < TM; ++i) aReg[i] = As[buf][rowBase + i][kk];
            #pragma unroll
            for (int j = 0; j < TN; ++j) bReg[j] = Bs[buf][kk][colBase + j];
            #pragma unroll
            for (int i = 0; i < TM; ++i)
                #pragma unroll
                for (int j = 0; j < TN; ++j)
                    acc[i][j] += aReg[i] * bReg[j];
        }

        __syncthreads();  // reader/writer turn-around on shared buffers
    }

    // Store the register tile to C.
    const int goutRow = blockRow + rowBase;
    const int goutCol = blockCol + colBase;
    #pragma unroll
    for (int i = 0; i < TM; ++i)
        #pragma unroll
        for (int j = 0; j < TN; ++j)
            C[(size_t)(goutRow + i) * N + (goutCol + j)] = acc[i][j];
}

// ---------------------------------------------------------------------------
// Fallback: arbitrary N. Register-blocked + shared tiled, guarded loads.
// ---------------------------------------------------------------------------
__global__ static void gemmKernelGuarded(const float* __restrict__ A,
                                         const float* __restrict__ B,
                                         float* __restrict__ C, int N) {
    __shared__ float As[BM][BK + 2];
    __shared__ float Bs[BK][BN + 2];

    const int numKTiles = (N + BK - 1) / BK;

    const int blockRow = blockIdx.y * BM;
    const int blockCol = blockIdx.x * BN;

    const int row = blockRow + threadIdx.y * TM;
    const int col = blockCol + threadIdx.x * TN;

    float acc[TM][TN];
    #pragma unroll
    for (int i = 0; i < TM; ++i)
        #pragma unroll
        for (int j = 0; j < TN; ++j) acc[i][j] = 0.0f;

    // Cooperative load of the A and B shared tiles (BM*BK + BK*BN entries,
    // 256 threads total => loop of ceil(...)).
    const int aTotal = BM * BK;
    const int bTotal = BK * BN;
    const int tid = threadIdx.y * BX + threadIdx.x;
    const int aIters = (aTotal + 255) / 256;
    const int bIters = (bTotal + 255) / 256;

    for (int t = 0; t < numKTiles; ++t) {
        const int kStart = t * BK;

        // ---- load A tile (BM x BK) ----
        for (int e = 0; e < aIters; ++e) {
            const int idx = tid + e * 256;
            if (idx < aTotal) {
                const int r = idx / BK;
                const int k = idx % BK;
                const int gRow = blockRow + r;
                const int gCol = kStart + k;
                As[r][k] = (gRow < N && gCol < N) ? A[(size_t)gRow * N + gCol] : 0.0f;
            }
        }

        // ---- load B tile (BK x BN) ----
        for (int e = 0; e < bIters; ++e) {
            const int idx = tid + e * 256;
            if (idx < bTotal) {
                const int k = idx / BN;
                const int c = idx % BN;
                const int gRow = kStart + k;
                const int gCol = blockCol + c;
                Bs[k][c] = (gRow < N && gCol < N) ? B[(size_t)gRow * N + gCol] : 0.0f;
            }
        }
        __syncthreads();

        #pragma unroll
        for (int kk = 0; kk < BK; ++kk) {
            float aReg[TM], bReg[TN];
            #pragma unroll
            for (int i = 0; i < TM; ++i) aReg[i] = As[threadIdx.y * TM + i][kk];
            #pragma unroll
            for (int j = 0; j < TN; ++j) bReg[j] = Bs[kk][threadIdx.x * TN + j];
            #pragma unroll
            for (int i = 0; i < TM; ++i)
                #pragma unroll
                for (int j = 0; j < TN; ++j)
                    acc[i][j] += aReg[i] * bReg[j];
        }
        __syncthreads();
    }

    // Guarded store.
    #pragma unroll
    for (int i = 0; i < TM; ++i) {
        const int r = blockRow + threadIdx.y * TM + i;
        if (r >= N) break;
        #pragma unroll
        for (int j = 0; j < TN; ++j) {
            const int c = blockCol + threadIdx.x * TN + j;
            if (c < N) C[(size_t)r * N + c] = acc[i][j];
        }
    }
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    if (N % BM == 0 && N % BN == 0 && N % BK == 0) {
        dim3 block(BX, BY);
        dim3 grid(N / BN, N / BM);
        gemmKernelAligned<<<grid, block>>>(dA, dB, dC, N);
    } else {
        dim3 block(BX, BY);
        dim3 grid((N + BN - 1) / BN, (N + BM - 1) / BM);
        gemmKernelGuarded<<<grid, block>>>(dA, dB, dC, N);
    }
}

