// Compare launchGemm (gemm.cu) vs cuBLAS for a fixed NxN sgemm.
#include "src/gemm.cuh"
#include <cublas_v2.h>
#include <cuda_runtime.h>
#include <cstdio>
#include <cstdlib>
#include <vector>

#define CK(c) do{cudaError_t e=(c); if(e!=cudaSuccess){fprintf(stderr,"CUDA %s\n",cudaGetErrorString(e));exit(1);}}while(0)

int main(int argc,char**argv){
    int N = argc>1?atoi(argv[1]):2048;
    size_t bytes=(size_t)N*N*sizeof(float);
    float *dA,*dB,*dC1,*dC2;
    CK(cudaMalloc(&dA,bytes)); CK(cudaMalloc(&dB,bytes));
    CK(cudaMalloc(&dC1,bytes)); CK(cudaMalloc(&dC2,bytes));
    std::vector<float> A(N*N),B(N*N);
    for(size_t i=0;i<(size_t)N*N;i++){A[i]=(float)(i%7)/7.0f-0.5f;B[i]=(float)(i%5)/5.0f-0.5f;}
    CK(cudaMemcpy(dA,A.data(),bytes,cudaMemcpyHostToDevice));
    CK(cudaMemcpy(dB,B.data(),bytes,cudaMemcpyHostToDevice));

    cublasHandle_t h; cublasCreate(&h);
    float alpha=1.0f,beta=0.0f;

    // cuBLAS (C = alpha*A*B + beta*C). Row-major => use CUBLAS_OP_N; cublas is col-major
    // but for square with op N it computes C(rm) = A*B correctly since both sides row-major.
    int repeats=50;  // warmup + measure
    for(int i=0;i<repeats;i++)
        cublasSgemm(h,CUBLAS_OP_N,CUBLAS_OP_N,N,N,N,&alpha,dA,N,dB,N,&beta,dC2,N);
    CK(cudaDeviceSynchronize());
    cudaEvent_t x,y; cudaEventCreate(&x); cudaEventCreate(&y);
    float best=1e30f;
    for(int r=0;r<10;r++){
        cudaEventRecord(x);
        for(int i=0;i<repeats;i++)
            cublasSgemm(h,CUBLAS_OP_N,CUBLAS_OP_N,N,N,N,&alpha,dA,N,dB,N,&beta,dC2,N);
        cudaEventRecord(y); cudaEventSynchronize(y);
        float ms; cudaEventElapsedTime(&ms,x,y);
        float per=ms/repeats; if(per<best)best=per;
    }
    double cub=2.0*(double)N*N*N/best/1e6;
    printf("cuBLAS N=%d: %.2f ms -> %.2f TFLOP/s\n",N,best,cub);

    // my kernel
    repeats=200;
    best=1e30f;
    for(int r=0;r<8;r++){
        cudaEventRecord(x);
        for(int i=0;i<repeats;i++) launchGemm(dA,dB,dC1,N);
        cudaEventRecord(y); cudaEventSynchronize(y);
        float ms; cudaEventElapsedTime(&ms,x,y);
        float per=ms/repeats; if(per<best)best=per;
    }
    double mine=2.0*(double)N*N*N/best/1e6;
    printf("mine    N=%d: %.2f ms -> %.2f TFLOP/s  (ratio %.3f)\n",N,best,mine,mine/cub);
    return 0;
}

// Compare launchGemm vs cuBLAS for fixed NxN sgemm, interleaved, best-of.
#include "src/gemm.cuh"
#include <cublas_v2.h>
#include <cuda_runtime.h>
#include <cstdio>
#include <cstdlib>
#include <vector>

#define CK(c) do{cudaError_t e=(c); if(e!=cudaSuccess){fprintf(stderr,"CUDA %s\n",cudaGetErrorString(e));exit(1);}}while(0)

static double timeBoth(float*bestm, float*bestc){
    // time my kernel and cublas each 'reps' times; return best ms for each
    return 0.0;
}

int main(int argc,char**argv){
    int N = argc>1?atoi(argv[1]):2048;
    size_t bytes=(size_t)N*N*sizeof(float);
    float *dA,*dB,*dC1,*dC2;
    CK(cudaMalloc(&dA,bytes)); CK(cudaMalloc(&dB,bytes));
    CK(cudaMalloc(&dC1,bytes)); CK(cudaMalloc(&dC2,bytes));
    std::vector<float> A(N*N),B(N*N);
    for(size_t i=0;i<(size_t)N*N;i++){A[i]=(float)(i%7)/7.0f-0.5f;B[i]=(float)(i%5)/5.0f-0.5f;}
    CK(cudaMemcpy(dA,A.data(),bytes,cudaMemcpyHostToDevice));
    CK(cudaMemcpy(dB,B.data(),bytes,cudaMemcpyHostToDevice));

    cublasHandle_t h; cublasCreate(&h);
    float alpha=1.0f,beta=0.0f;
    cudaEvent_t x,y; cudaEventCreate(&x); cudaEventCreate(&y);

    // Warmup
    for(int i=0;i<30;i++){ cublasSgemm(h,CUBLAS_OP_N,CUBLAS_OP_N,N,N,N,&alpha,dA,N,dB,N,&beta,dC2,N); launchGemm(dA,dB,dC1,N);}
    CK(cudaDeviceSynchronize());

    int reps=100;
    float bestm=1e30f,bestc=1e30f;
    // interleave, best-of-6
    for(int r=0;r<6;r++){
        cudaEventRecord(x);
        for(int i=0;i<reps;i++) launchGemm(dA,dB,dC1,N);
        cudaEventRecord(y); cudaEventSynchronize(y);
        float ms; cudaEventElapsedTime(&ms,x,y); ms/=reps; if(ms<bestm)bestm=ms;

        cudaEventRecord(x);
        for(int i=0;i<reps;i++) cublasSgemm(h,CUBLAS_OP_N,CUBLAS_OP_N,N,N,N,&alpha,dA,N,dB,N,&beta,dC2,N);
        cudaEventRecord(y); cudaEventSynchronize(y);
        float ms; cudaEventElapsedTime(&ms,x,y); ms/=reps; if(ms<bestc)bestc=ms;
    }
    double gm=2.0*(double)N*N*N/bestm/1e9;
    double gc=2.0*(double)N*N*N/bestc/1e9;
    printf("N=%d  mine %.3f ms (%.2f GF/s)   cublas %.3f ms (%.2f GF/s)   ratio mine/cublas=%.3f\n",
           N,bestm,gm,bestc,gc,gm/gc);
    return 0;
}

